CREATE TABLE merchant_discount_limit (employee_id uuid PRIMARY KEY REFERENCES merchant_employee(id),venue_id uuid NOT NULL REFERENCES merchant_venue(id),max_basis_points integer NOT NULL CHECK(max_basis_points BETWEEN 0 AND 10000),max_minor integer NOT NULL CHECK(max_minor >= 0));
CREATE TABLE merchant_discount (order_id uuid PRIMARY KEY REFERENCES merchant_order(id),venue_id uuid NOT NULL REFERENCES merchant_venue(id),order_revision integer NOT NULL,kind text NOT NULL CHECK(kind IN ('PERCENT','FIXED')),value integer NOT NULL CHECK(value>0),amount_minor integer NOT NULL CHECK(amount_minor>0),reason text NOT NULL,requested_by text NOT NULL,status text NOT NULL CHECK(status IN ('PENDING','APPLIED')),approved_by text,approved_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
